# Deutsche Uebersetzungen: Param/Item/Food.csv (110 Name/Beschreibung-Paare)

_PATH = "Param/Item/Food.csv"
_PAIRS = [
    ("Hasenfleisch", "Man sagt, wer sich von den Tieren nährt, von denen er isst,\ngewinnt ihre Kräfte. Vielleicht verleiht dir dieses Fleisch\ndie Geschicklichkeit und List eines Hasen."),
    ("Schweinefleisch", "Bekannt für seine Vitalität ist das Fleisch der Schweinedämonen\nwesentlich zum Muskelaufbau. Man sagt, Schweinefleisch sei\ndas meistgegessene Fleisch in Ouka, einem Land jenseits des Meeres."),
    ("Keilerfleisch", "Im Vergleich zu anderen Dämonen seiner Art ist die Stärke\neines Keilers unübertroffen. Das Fleisch hat einen leichten\nwilden Geruch; es muss sanft gekocht werden, um den feinen\nGeschmack zu entfalten."),
    ("Hirschfleisch", "Hirschfleisch muss vor dem Kochen richtig vorbereitet werden,\ndoch das Ergebnis ist ein wahrhaft magischer Fleischbrocken,\nder sich zu jedem Gericht paaren lässt."),
    ("Bärenfleisch", "Selbst mächtige Götter staunen über die Stärke und Vitalität,\ndie in Bärenfleisch steckt. Es mag mühsam zu kochen sein,\ndoch das Ergebnis ist den Aufwand mehr als wert."),
    ("Dachsfleisch", "Seltsamerweise variiert der Geschmack von Dachsfleisch\nje nach erlegtem Tier. Ob ein Bissen schmackhaft ist,\nhängt mehr vom Glück ab als vom Können."),
    ("Schildkrötenfleisch", "Schildkrötenfleisch wird oft wegen seiner verjüngenden\nEigenschaften als Medizin genutzt. Iss davon, wenn dir\ndie Vitalität ausgeht."),
    ("Sperlingsfleisch", "Ah, der Sperling... die Plage jedes Reisfeldes.\nSeine Knusprigkeit beim Kochen ist schlicht göttlich.\nSo klein er auch ist, sein Fleisch steckt voller magischer Energie."),
    ("Fasanenfleisch", "Die List eines Fasans kann ärgern, doch sein Fleisch\nmag deine Geschicklichkeit stärken. Die Textur ist eher\nschlicht, der Geschmack gilt jedoch als köstlich."),
    ("Entenfleisch", "Entenfleisch wird wegen seines saftigen, hochwertigen Fetts\nverehrt. Nach dem Essen kehrt die Vitalität zurück\nund das Glück wächst."),
    ("Schmerle", "Urteile nicht über die Schmerle wegen ihrer kleinen Größe,\ndenn sie steckt voller verborgener Vitalität. Sei dankbar,\nwenn du morgen deine Arbeit verrichtest."),
    ("Ayu", "Ein glückbringender Fisch, seit uralten Zeiten\nfür die Weissagung genutzt. Ich muss sagen:\ner gehört zu meinen Lieblingen!"),
    ("Karpfen", "Karpfen sollen die Kraft haben, die Gesundheit der Frauen\nzu fördern. Mich wundert, wie man den Schlammgeruch loswird.\nDas muss das Zeichen eines wahrhaft talentierten Kochs sein."),
    ("Masu-Lachs", "Weil sie klares Wasser lieben, haben diese Fische\neinen großartigen Duft. Ich vermute, in ihren Körpern\nwirbelt reichlich spirituelle Energie."),
    ("Saibling", "Diese Fische haben einen hitzigen Appetit und damit\nreichlich Vitalität. Ihr Geschmack ist einfach, aber kräftig."),
    ("Karausche", "Diese Fische findet man in fast jedem Fluss Yanatos.\nDer Geschmack hin oder her - satt werden sie sicher."),
    ("Lachs", "Lachs gilt als Fisch der Götter, denn er kommt mit der\nspirituellen Energie zur Welt, die es erlaubt, vom Tod zum Leben\nzurückzukehren, und mit der Kraft, stromaufwärts zu schwimmen."),
    ("Stint", "Diese Fische lieben kaltes Wasser und sind vom Glück begnadet.\nIhr zartes Fleisch eignet sich perfekt zum Braten."),
    ("Hering", "Es ist selten, diese Fische ganz aus dem nördlichen Meer\nkommen zu sehen. Das köstliche Fett ihres Fleisches\nwird deine spirituellen Fähigkeiten mehren."),
    ("Aal", "Ein langer Flussfisch voller gesunder Nährstoffe.\nSeine zappelnde Energie verleiht Geschicklichkeit und Stärke."),
    ("Korbmuschel", "Muscheln saugen die spirituelle Energie aus Schlamm und Sand.\nZu große Muscheln neigen dazu, in Dämonen zu verfallen,\nwenn sie zu viel negativer Energie ausgesetzt sind."),
    ("Ei", "Ein hart schaliges Vogelei. Es erweitert nicht nur deinen\nKochvorrat, sondern hat, wie ich hörte, auch viele\ngesundheitliche Vorteile."),
    ("Heuschrecke", "Dieser Schädling mag unsere Reisähren verschlingen,\nals Zutat verleiht er Gerichten Vitalität."),
    ("Bienenlarve", "Dieses Insekt wird wegen seiner gesundheits- und\nvitalitätsfördernden Eigenschaften geschätzt. Was das\nAussehen anbelangt... Man gewöhnt sich an alles, vermute ich."),
    ("Braunreis", "Obwohl dieser Reis nicht geschält ist, bevorzugen viele\nseinen Duft und Geschmack. Er soll nährstoffreicher sein\nals weißer Reis."),
    ("Mischreis", "Dieser Reis wurde nur teilweise geschält. Er vereint\ndaher die Eigenschaften von weißem und braunem Reis."),
    ("Weißreis", "Dieser perlweiße Reis wurde tadellos poliert.\nDiese Körner sind die Seele des Volkes von Yanato!"),
    ("Weizen", "Obwohl er zu den fünf Körnern zählt, ist der auf dieser\nInsel geerntete Weizen nicht für den Anbau geeignet.\nAls Zutat darfst du ihn natürlich trotzdem verwenden."),
    ("Hirse", "Eines der fünf Körner und die ältesten Kulturen Yanatos.\nEr sättigt nicht besonders, tut aber offenkundig\nder Gesundheit gut."),
    ("Sanwa-Hirse", "Eines der fünf Körner und eine der beliebtesten Kulturen Yanatos,\ndank ihrer Fähigkeit, auch in schlechtem Boden zu wachsen.\nSie enthält zudem einen Hauch spiritueller Energie."),
    ("Bohne", "Eines der fünf Körner und eine Quelle großer Kraft.\nAuch als Zutat in herrlichen Würzmitteln wie Miso\nund Sojasauce wird sie verwendet."),
    ("Buchweizen", "Eine robuste Pflanze, angebaut, um Hungersnot abzuwenden.\nNeben der Sättigung gewährt sie dir womöglich die Fähigkeit,\nin der Schlacht noch mehr Techniken einzusetzen."),
    ("Tekusari", "Auch wenn die Wurzeln dieser robusten Pflanze giftig sind,\nkann man sie nach dem Zerstoßen und Einweichen in Wasser\nessen. Viele Bauern pflanzen sie für schlechte Ernten an."),
    ("Eichel", "Dies ist die hart schalige Frucht eines Laubbaums.\nMag sie auch karg sein - jedes Bisschen hilft."),
    ("Taro", "Taro ist eine Wurzelpflanze, die das Volk von Yanato speist\nseit lange vor den fünf Körnern. Heute ist sie der Star\nvieler Abendessensgerichte."),
    ("Kartoffel", "Die Kartoffel ist eine Art Taro, die in eisigen Landen wächst\nund erst kürzlich Yanato erreicht hat. Als Wurzelpflanze\nsättigt sie ordentlich und verleiht womöglich Vitalität."),
    ("Zwiebel", "Dies scheint eine rundliche Variante der Frühlingszwiebel zu sein.\nSie schenkt scheinbar Glück und wird von Kriegern des\nWestens bevorzugt. Außerdem bekannt dafür, beim Schneiden\nTränen herauszupressen."),
    ("Warabi", "Ein äußerst bitterer Farn, der häufig in der Wildnis nahegelegener\nSiedlungen wächst. Sein kräftiger Geschmack mag dir die\nFähigkeit zu zusätzlichen Techniken verleihen."),
    ("Schachtelhalm", "Diese Triebe des Schachtelhalms sind ein Heilkraut.\nEr sammelt spirituelle Energie aus dem Boden, wodurch er\neinen bittersüßen Geschmack mit Frühlingsnostalgie erhält."),
    ("Beifuß", "Ein duftendes Kraut, das im Frühling zu finden ist.\nBekannt für seine vielfältigen Heilwirkungen, von denen\ndie nützlichste die Vitalitätssteigerung ist."),
    ("Sieben Kräuter", "Doppelkraut, Kresse, Vogelknöterich, Knorpelkraut,\nGänseblümchen, Rübe und Radieschen. Wer alle sieben findet, dem bringt\ndie Sage zufolge besonderes Glück."),
    ("Wurzelfrüchte", "Klette, Karotten, Radieschen und dergleichen sind\nsämtlich köstlich und voller Nährstoffe. Ob dir der Geschmack\nzusagt - sie machen dich sicher gesünder."),
    ("Gurke", "Ein saftiges Gemüse, süß und leicht bitter zugleich.\nBesonders geliebt bei den wasserbewohnenden Kappa."),
    ("Mais", "Eine unbekannte Pflanze aus winzigen gelben Körnern.\nMeines Wissens wird diese Kultur in Yanato nicht angebaut."),
    ("Pilz", "Um die Bäume der Berge wachsen die wunderbarsten Pilzarten,\ndarunter Maitake, Shimeji und Shiitake. Ihre Nährstoffe\nstärken deine Muskeln und verleihen Kraft."),
    ("Matsutake", "Mein Wort... Dieser Pilz gilt als außergewöhnlich selten!\nDu musst unglaublich viel Glück haben, ihn gefunden zu haben.\nVielleicht bringt sein Verzehr dir noch mehr Glück."),
    ("Kastanie", "Die harte Schale verbirgt einen süßen Kern. Zudem\nstärkt ihr Verzehr deine spirituellen Kräfte."),
    ("Ginkgonuss", "Diese Nüsse stammen aus den Samen der Ginkgobäume.\nDie weiblichen Bäume bilden Samenanlagen, die Gesundheit\nund langes Leben gewähren sollen."),
    ("Kaki", "Die Kakis dieser Insel reichen von streng bis köstlich süß.\nDu musst großes Glück gehabt haben, auf einen süßen\ngelangt zu sein... dieses Mal."),
    ("Knoblauch", "Eine Wildpflanze mit ordentlichem Biss. Ihr kräftiger\nGeschmack tut Wunder für deine Vitalität... weniger\nfür deinen Atem."),
    ("Wasabi", "Diese Wildpflanze wächst häufig an klaren Bächen und\ndient als Würzmittel. Ihre übertriebene Schärfe öffnet\ndeine Nebenhöhlen und bringt deine Energie in Wallung."),
    ("Ingwer", "Eine Wurzel, die seit Langem sowohl gegen Gerüche\nals auch zum Würzen von Speisen genutzt wird. Sie wärmt\ngarantiert, stärkt und verbessert dein Technikpotenzial."),
    ("Frühlingszwiebel", "Roh gegessen ist sie scharf und knusprig, gekocht\nbringt sie ihre innere Süße hervor. Sie hat auch medizinische\nEigenschaften und soll selbst die Kampfgeschicklichkeit mehren."),
    ("Pflaume", "Der Hauch von Süße im streng sauren Geschmack ist\nwie eine Metapher für das Erziehen von Kindern.\nAnders als die Elternschaft kann ihr Verzehr auch der\nGesundheit zuträglich sein."),
    ("Salz", "Salz ist ein Mineral, das als Konservierungsmittel\nnicht nur für Speisen, sondern auch für Geist und Körper\nunverzichtbar ist. Es soll die Kraft haben, allerlei\nUnreinheiten zu reinigen."),
    ("Zucker", "Ein Süßungsmittel aus Zuckerrohr, das auf einer Insel im\nSüdmeer wächst. Er ist hochwertig und hat sich nun\nausbreitet; selbst einfache Leute können ihn genießen."),
    ("Sesam", "Das Samengewächs, mit dem viele Speisen gewürzt werden.\nSeit uralten Zeiten geschätzt und zudem sehr nährstoffreich."),
    ("Kombu-Alge", "Eine Algenart, die in Yanato seit Langem als Suppenbasis\nund allgemeine Zutat beliebt ist."),
    ("Tee", "Auch wenn die Teepflanze aus Ouka stammt, wuchs auf dieser\nInsel bereits eine Art. Ihre Blätter dienen der Weissagung.\nIn heißer Brühe getrunken bringt sie Glück."),
    ("Kryptotaenie", "Ein Heilkraut, das gegen zahlreiche Leiden wirkt.\nBesonders nützlich als Mittel gegen Gift... und zudem\nköstlich als Tempura."),
    ("Suppenbrühe", "Hergestellt aus Zutaten, die ausgekocht werden,\num ihren Geschmack freizusetzen. In jeder Küche unverzichtbar."),
    ("Miso", "Eine Paste aus zerstoßenen Bohnen, Malz und Salz,\ndie gemischt und dann fermentiert wird. Schmackhaft,\nsättigend und anregend. Perfekter geht es nicht!"),
    ("Sojasauce", "Eine flüssige Würze aus fermentierter Sojabohnenpaste.\nBelebe damit Nudelgerichte wie Udon und Soba."),
    ("Öl", "Gereinigtes Öl, sorgfältig von den Rückständen gefiltert.\nEin Leben im Überfluss bleibt ohne diese kostbare Substanz\nunvollständig."),
    ("Pflanzenöl", "Ein rohes Öl, gewonnen aus Perillasamen und dergleichen.\nEs enthält Rückstände und ist eher scharf, weshalb es\nin dieser Form schwer zu verwenden ist."),
    ("Fischöl", "Ein rohes Fischöl. Es enthält Rückstände und ist eher\nscharf, weshalb es in dieser Form schwer zu verwenden ist."),
    ("Eis", "Bekanntes Wasser, in kalter Gegend gefroren.\nEs hält Lebensmittel kühl und bewahrt sie vor dem Verderben...\nbis es schmilzt, versteht sich."),
    ("Essig", "Eine Würze, gewonnen durch Fermentation von Malzreis\nzu Essigsäure. Sein saurer Geschmack lindert die Erschöpfung."),
    ("Gesundheitspulver", "Ein Pulver, das deine Gesundheit vorübergehend erhöht.\nLöse es in Wasser, um es zu dir zu nehmen."),
    ("Technikpulver", "Ein Pulver, das deine Technikkapazität vorübergehend erhöht.\nLöse es in Wasser, um es zu dir zu nehmen."),
    ("Stärkepulver", "Ein Pulver, das deine Stärke vorübergehend erhöht.\nLöse es in Wasser, um es zu dir zu nehmen."),
    ("Vitalitätspulver", "Ein Pulver, das deine Vitalität vorübergehend erhöht.\nLöse es in Wasser, um es zu dir zu nehmen."),
    ("Magiepulver", "Ein Pulver, das deine Magie vorübergehend erhöht.\nLöse es in Wasser, um es zu dir zu nehmen."),
    ("Glückspulver", "Ein Pulver, das dein Glück vorübergehend erhöht.\nLöse es in Wasser, um es zu dir zu nehmen."),
    ("Sättigungspulver", "Ein Pulver, das deine Sättigung vorübergehend erhöht.\nLöse es in Wasser, um es zu dir zu nehmen."),
    ("Gesundheitsflocken", "Mit einer medizinischen Basis kombiniert\nerhöhen diese Flocken deine Grundgesundheit."),
    ("Stärkeflocken", "Mit einer medizinischen Basis kombiniert\nerhöhen diese Flocken deine Grundstärke."),
    ("Vitalitätsflocken", "Mit einer medizinischen Basis kombiniert\nerhöhen diese Flocken deine Grundvitalität."),
    ("Magieflocken", "Mit einer medizinischen Basis kombiniert\nerhöhen diese Flocken deine Grundmagie."),
    ("Glücksflocken", "Mit einer medizinischen Basis kombiniert\nerhöhen diese Flocken dein Grundglück."),
    ("Appetitflocken", "Mit einer medizinischen Basis kombiniert\nerhöhen diese Flocken deinen Grundappetit."),
    ("Medizinische Basis", "Mit Flocken kombiniert erhöht diese medizinische Basis\ndeine verschiedenen Fähigkeiten."),
    ("Malz", "Eine dicke, sirupartige Masse aus gedämpftem und\nfermentiertem Reis. Sie ist die Grundlage vieler Rezepte\nund Würzmittel."),
    ("Reiskleie", "Eine Ansammlung von Rückständen aus dem Schälprozess,\neinschließlich Schalen und Keime. Sie ist sehr vielseitig:\nnicht nur zum Kochen, sondern auch zum Reinigen geeignet."),
    ("Mochi", "Eine Art Kuchen, hergestellt durch Zugabe von Wasser zu Reis,\nZerstoßen und Aushärten. Er ist köstlich gekocht und\ngeröstet - und hervorragend haltbar!"),
    ("Tofu", "Dieser Bohnenquark entsteht, indem Sojasaft mit einer\nSalzlösung gemischt und aushärten gelassen wird."),
    ("Reiskuchen", "Dieser Reis wurde mit Wasser gemischt, gestampft und\nrund geformt. In alten Zeiten brachten die Menschenkinder\ndies regelmäßig den Göttern als Opfer dar."),
    ("Getrocknetes ~Auto~", "~Auto~, in der Sonne getrocknet, um Verderben zu verhindern.\nDie meisten Lebensmittel halten länger, wenn man ihnen\ndas Wasser entzieht."),
    ("Geräuchertes ~Auto~", "~Auto~, gesalzen, geräuchert und getrocknet.\nDer rauchige Duft paart sich wunderbar mit dem kräftigen Geschmack."),
    ("Eingelegtes ~Auto~", "~Auto~, in gesalzener Reiskleie eingelegt.\nSein kräftiger Geschmack überflutet dich schon nach einem Bissen."),
    ("~Auto~-Sushi", "Eingelegtes und gesalzenes ~Auto~ in Reis verpackt.\nEinige Sonderlinge behaupten, es werde mit jedem Schnuppern\nköstlicher - davon lasse ich mich nicht so leicht überzeugen."),
    ("Käse", "Ein Milchprodukt, das in den westlichen Ländern weit\nverehrt wird. Man könnte es mit Yanatos Kondensmilch vergleichen."),
    ("Getrockneter Hering", "Das ist offenbar Hering, mit Kräutern, Essig und Salz\nkonserviert. Myrthe sagt, es sei ein berühmtes Produkt\nihrer Heimat Ventania. Es ist nicht ganz unähnlich wie Sushi."),
    ("Getrockneter Kochreis", "Ein Korn, in der Sonne getrocknet und seines Wassers beraubt.\nAm besten ist es, es in heißem Wasser aufzuweichen,\nbevor man es isst."),
    ("Getrockneter Lachs", "Gesalzener Lachs, in der Seeluft getrocknet.\nEr hält zwar eine Weile, ist aber unglaublich salzig.\nPass auf, dass du dich nicht davon satt isst."),
    ("Getrockneter Tarostängel", "Der getrocknete Stängel einer Taropflanze, zu einer Schnur\ngedreht. Oft von Soldaten auf dem Weg zum Schlachtfeld\nmitgeführt."),
    ("Getrocknete Kaki", "Eine Kaki, unter dem Hausdach aufgehängt und bis zum\npudrigen Belag getrocknet. Ihr bezaubernder Süßengeschmack\nist schlicht göttlich! Wahrhaft der beste Schatz des Herbstes."),
    ("Eingelegter Wasabi", "Gehackter Wasabi, in Sake eingelegt. Passt gut zu Alkohol --\nvielleicht ein bisschen zu gut. Vorsicht, nicht zu viel zu trinken."),
    ("Eingelegte getrocknete Pflaume", "Eine in Salz eingelegte Pflaume. Sie wird nicht nur als\nMarschnahrung genutzt, sondern auch als Medizin gegen Gift."),
    ("Quellwasser", "Ah, dies muss klares Wasser sein, das aus einer Quelle im Tal\ngeschöpft wurde. Es ist, das muss ich zugeben, zum Trinken\nund Kochen besser als das Wasser um den Bergpass."),
    ("Berühmtes Wasser", "Wasser, das für seine Reinheit bekannt ist, aus festem Eis\ngeschmolzen. Es ist wohl das hochwertigste Wasser,\ndas wir auf dieser Insel finden können."),
    ("Kuchikami-Sake", "Ein mit menschlichem Speichel vergorener Alkohol.\nEr stinkt zum Himmel und ist schrecklich unhygienisch.\nNur die wahrhaft Mutigen trauen sich, ihn zu kosten."),
    ("Doburoku", "Ungefilterter, trüb-weißer Sake.\nVerbindet eine durchdringende Säure mit kräftigem, reisigem Geschmack."),
    ("Amazake", "Ein aus süß gemachtem Reis hergestelltes Getränk.\nLass dich vom Namen täuschen: dieses Getränk ist alkoholfrei.\nSanft süß und anregend."),
    ("Gereinigter Sake", "Ein klarer Alkohol, gefiltert und erhitzt.\nKräftiger Geschmack mit einem Hauch von Süße."),
    ("Heilsamer Sake", "Nährstoffreiche Wurzeln und Blätter wurden hinzugefügt,\num ihn zu einem Heilmittel zu machen. So bitter er schmeckt,\nmacht er dich wenigstens hartnäckig genug, den meisten\nGiften zu widerstehen."),
    ("Ginjo-Sake", "Ein Alkohol aus poliertem Reis, bei niedriger Temperatur\nvergoren. Sanft, schmackhaft und unglaublich aromatisch."),
    ("Daiginjo-Sake", "Ein Alkohol aus sorgfältig ausgewählten, perfekt polierten\nReiskörnern. Seine Durchsichtigkeit und überlegene Duftnote\nbezeugen seinen Rang als wahres Kunstwerk."),
    ("~Auto~-Shochu", "Ein starker Alkohol, destilliert aus Zutaten.\nDer Geschmack der verwendeten Getreidearten steigert seinen Genuss."),
    ("Bier", "Ein Alkohol aus dem fernen Westen, aus Weizen gebraut.\nMyrthes Lieblingsgetränk. Offenbar verbietet ihr Glaube\nden Genuss von Spirituosen nicht..."),
]

assert len(_PAIRS) == 110, f"erwartet 110, gefunden {len(_PAIRS)}"

DE_FOOD = {}
for _i, (_n, _c) in enumerate(_PAIRS, 1):
    DE_FOOD[(_PATH, f"NameEn#{_i}")] = _n
    DE_FOOD[(_PATH, f"CommentEn#{_i}")] = _c
